#include <stdio.h>

/* 闭区间二分查找：先运行基线，再逐个解释 TODO。 */
int binary_search(const int data[], int length, int target) {
    int left = 0;              /* TODO 1：为什么初始左端点是 0？ */
    int right = length - 1;    /* TODO 2：为什么闭区间右端点是 length - 1？ */

    while (left <= right) {     /* TODO 3：闭区间何时仍然有候选？ */
        int mid = left + (right - left) / 2; /* TODO 4：写出中点与溢出安全理由。 */

        if (data[mid] == target) {
            return mid;
        }
        if (data[mid] < target) {
            left = mid + 1;       /* TODO 5：mid 已比较过，哪一侧被排除？ */
        } else {
            right = mid - 1;
        }
    }
    return -1;
}

int main(void) {
    const int samples[] = {3, 8, 12, 17, 21, 29, 34, 40};
    const int length = (int)(sizeof(samples) / sizeof(samples[0]));
    const int targets[] = {3, 29, 40, 30, 1, 50};
    for (int i = 0; i < 6; ++i) {
        printf("target=%d index=%d\n", targets[i], binary_search(samples, length, targets[i]));
    }
    return 0;
}
